`timescale 1ns / 1ps
// tb_enigma_core.v - verifies enigma_core (+ plugboard) against the Python golden model.
//   1. Directed tests: published vector, double-stepping, plug errors, invalid keys, load/reset.
//   2. Vector file (+VEC=path, default sim/build/vectors.txt) generated by tools/gen_vectors.py.
// Prints "PASS" or "FAIL" on the last line; run via `python tools/run_sim.py`.
module tb_enigma_core;
    reg clk = 1'b0;
    always #5 clk = ~clk;                       // 100 MHz

    reg         rst = 1'b1;
    reg         load = 1'b0;
    reg  [14:0] start_pos = 15'd0;
    reg  [8:0]  rotor_sel = 9'd0;
    reg  [14:0] ring_set = 15'd0;
    reg         reflector_sel = 1'b0;
    reg  [9:0]  plug_en = 10'd0;
    reg  [49:0] plug_a = 50'd0;
    reg  [49:0] plug_b = 50'd0;
    reg         key_valid = 1'b0;
    reg  [4:0]  key_code = 5'd0;
    wire        busy, done, plug_error;
    wire [4:0]  lamp_code;
    wire [14:0] pos_out;

    enigma_core dut (
        .clk(clk), .rst(rst), .load(load), .start_pos(start_pos),
        .rotor_sel(rotor_sel), .ring_set(ring_set), .reflector_sel(reflector_sel),
        .plug_en(plug_en), .plug_a(plug_a), .plug_b(plug_b),
        .key_valid(key_valid), .key_code(key_code),
        .busy(busy), .done(done), .lamp_code(lamp_code), .pos_out(pos_out), .plug_error(plug_error)
    );

    integer errors = 0;
    integer checks = 0;

    task check;
        input [255:0] what;
        input integer got;
        input integer expected;
        begin
            checks = checks + 1;
            if (got !== expected) begin
                errors = errors + 1;
                if (errors <= 20)
                    $display("  MISMATCH %0s: got %0d expected %0d (t=%0t)", what, got, expected, $time);
            end
        end
    endtask

    // Press one key and wait for the result. result = 31 on timeout.
    task send;
        input  [4:0] c;
        output [4:0] result;
        integer n;
        begin
            @(negedge clk); key_code = c; key_valid = 1'b1;
            @(negedge clk); key_valid = 1'b0;
            n = 0;
            while (!done && n < 40) begin @(negedge clk); n = n + 1; end
            result = done ? lamp_code : 5'd31;
        end
    endtask

    task do_load;
        input [14:0] p;
        begin
            @(negedge clk); start_pos = p; load = 1'b1;
            @(negedge clk); load = 1'b0;
            @(negedge clk);
        end
    endtask

    function [14:0] pk;
        input [4:0] l, m, r;
        pk = {l, m, r};
    endfunction

    // ---- vector-file state -------------------------------------------------------
    integer fd, rc, v;
    integer rl, rm, rr, gl, gm, gr, pl, pm, pr, refl, npairs, len;
    integer ai [0:9];
    integer bi [0:9];
    integer pt [0:1023];
    integer ct [0:1023];
    integer i, j, vec_count;
    reg [4:0] res;
    reg [255:0] path_str;
    reg [8*200-1:0] vec_path;

    task rd;
        output integer value;
        begin
            rc = $fscanf(fd, "%d", value);
        end
    endtask

    initial begin
        if (!$value$plusargs("VEC=%s", vec_path)) vec_path = "sim/build/vectors.txt";
        if ($test$plusargs("VCD")) begin
            $dumpfile("sim/build/tb_enigma_core.vcd");
            $dumpvars(0, tb_enigma_core);
        end

        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        // ---- directed 1: published vector AAAAA -> BDZGO (I-II-III, UKW-B, AAA, AAA, no plugs)
        rotor_sel = {3'd0, 3'd1, 3'd2};
        do_load(pk(0, 0, 0));
        send(5'd0, res); check("BDZGO[0]", res, 1);
        send(5'd0, res); check("BDZGO[1]", res, 3);
        send(5'd0, res); check("BDZGO[2]", res, 25);
        send(5'd0, res); check("BDZGO[3]", res, 6);
        send(5'd0, res); check("BDZGO[4]", res, 14);
        check("pos after 5", pos_out, pk(0, 0, 5));

        // ---- directed 2: double-stepping ADU -> ADV -> AEW -> BFX -> BFY
        do_load(pk(0, 3, 20));
        send(5'd0, res); check("ADV", pos_out, pk(0, 3, 21));
        send(5'd0, res); check("AEW", pos_out, pk(0, 4, 22));
        send(5'd0, res); check("BFX", pos_out, pk(1, 5, 23));
        send(5'd0, res); check("BFY", pos_out, pk(1, 5, 24));

        // ---- directed 3: reciprocity with plugboard (encrypt then decrypt returns the plaintext)
        plug_en = 10'h007; plug_a = {35'd0, 5'd4, 5'd2, 5'd0}; plug_b = {35'd0, 5'd5, 5'd3, 5'd1}; // AB CD EF
        check("plug_error valid", plug_error, 0);
        do_load(pk(5, 6, 7));
        begin : recip
            reg [4:0] c0, c1, c2, p0, p1, p2;
            send(5'd7, c0); send(5'd4, c1); send(5'd11, c2);
            do_load(pk(5, 6, 7));
            send(c0, p0); send(c1, p1); send(c2, p2);
            check("recip 0", p0, 7); check("recip 1", p1, 4); check("recip 2", p2, 11);
            check("never self 0", (c0 == 5'd7), 0);
            check("never self 1", (c1 == 5'd4), 0);
        end

        // ---- directed 4: invalid plugboards raise plug_error
        plug_en = 10'h001; plug_a = 50'd0; plug_b = {45'd0, 5'd0};          // A with A
        #1; check("plug self", plug_error, 1);
        plug_en = 10'h003; plug_a = {40'd0, 5'd0, 5'd0}; plug_b = {40'd0, 5'd3, 5'd2}; // A-C, A-D (A reused)
        #1; check("plug reuse", plug_error, 1);
        plug_en = 10'h001; plug_a = {45'd0, 5'd30}; plug_b = {45'd0, 5'd1};   // letter 30 out of range
        #1; check("plug range", plug_error, 1);
        plug_en = 10'd0; plug_a = 50'd0; plug_b = 50'd0;
        #1; check("plug cleared", plug_error, 0);

        // ---- directed 5: out-of-range key ignored (no done, no step)
        do_load(pk(0, 0, 0));
        send(5'd30, res); check("bad key ignored", res, 31);
        check("bad key no step", pos_out, pk(0, 0, 0));

        // ---- directed 6: reset returns the window to AAA
        do_load(pk(9, 9, 9));
        @(negedge clk); rst = 1'b1; @(negedge clk); rst = 1'b0; @(negedge clk);
        check("reset pos", pos_out, pk(0, 0, 0));

        // ---- vector file -----------------------------------------------------------------
        vec_count = 0;
        fd = $fopen(vec_path, "r");
        if (fd == 0) begin
            $display("  cannot open vector file %0s", vec_path);
            errors = errors + 1;
        end else begin
            rd(rl);
            while (rc == 1) begin
                rd(rm); rd(rr); rd(gl); rd(gm); rd(gr); rd(pl); rd(pm); rd(pr); rd(refl); rd(npairs);
                plug_en = 10'd0; plug_a = 50'd0; plug_b = 50'd0;
                for (i = 0; i < 10; i = i + 1) begin
                    rd(ai[i]); rd(bi[i]);
                    plug_a[i*5 +: 5] = ai[i];
                    plug_b[i*5 +: 5] = bi[i];
                    if (i < npairs) plug_en[i] = 1'b1;
                end
                rd(len);
                for (i = 0; i < len; i = i + 1) rd(pt[i]);
                for (i = 0; i < len; i = i + 1) rd(ct[i]);

                rotor_sel = {rl[2:0], rm[2:0], rr[2:0]};
                ring_set = {gl[4:0], gm[4:0], gr[4:0]};
                reflector_sel = refl[0];
                do_load(pk(pl[4:0], pm[4:0], pr[4:0]));
                for (j = 0; j < len; j = j + 1) begin
                    send(pt[j][4:0], res);
                    check("vector letter", res, ct[j]);
                end
                check("vector plug_error", plug_error, 0);
                vec_count = vec_count + 1;
                rd(rl);   // first field of the next line (or EOF)
            end
            $fclose(fd);
            $display("  %0d vectors from file", vec_count);
        end

        $display("tb_enigma_core: %0d checks, %0d errors", checks, errors);
        if (errors == 0 && vec_count > 0) $display("PASS"); else $display("FAIL");
        $finish;
    end

    initial begin
        #200_000_000;
        $display("FAIL: testbench timeout");
        $finish;
    end
endmodule
